// route-inventory: GET /rules
// Independent acceptance. Builder: do not edit this file or its fixture helper.
import { afterAll, beforeAll, describe, expect, it } from "vitest";
import { mdRules } from "../src/ai-friendly/md";
import * as rulesContent from "../src/rules-content";
import { RULES } from "../src/rules-content";
import {
  changedRuleRows,
  createRulesFixture,
  LONG_RULE_LABEL,
  RULE_COPY,
  RULE_ORIGIN,
} from "./helpers/rules-anchor-fixture";

const text = (html: string) =>
  html
    .replace(/<!--[\s\S]*?-->|<[^>]*>/g, "")
    .replace(/&amp;/g, "&")
    .trim();
const attribute = (tag: string, name: string) =>
  tag.match(new RegExp(`\\b${name}="([^"]*)"`))?.[1] ?? "";
const items = (html: string) => {
  const list = html.match(/<ol\b[^>]*data-testid="rules-list"[^>]*>([\s\S]*?)<\/ol>/)?.[1] ?? "";
  return [...list.matchAll(/<li\b[^>]*>[\s\S]*?<\/li>/g)].map(([item]) => item);
};
function accessibleName(element: string, html: string): string {
  const opening = element.slice(0, element.indexOf(">") + 1);
  const label = attribute(opening, "aria-label");
  if (label) return label;
  const labelledBy = attribute(opening, "aria-labelledby");
  if (labelledBy)
    return labelledBy
      .split(/\s+/)
      .map((id) => {
        const escaped = id.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
        return text(
          html.match(new RegExp(`<([\\w-]+)[^>]*id="${escaped}"[^>]*>([\\s\\S]*?)<\\/\\1>`))?.[2] ??
            "",
        );
      })
      .join(" ");
  return text(element);
}
function jumpLinks(html: string) {
  const nav = [...html.matchAll(/<nav\b[^>]*>[\s\S]*?<\/nav>/g)]
    .map(([value]) => value)
    .filter((value) => accessibleName(value, html) === "Jump to a rule");
  expect(nav, "RULE-01: one labelled native jump navigation").toHaveLength(1);
  return [...nav[0]!.matchAll(/<a\b[^>]*>[\s\S]*?<\/a>/g)].map(([value]) => value);
}
function idsForRules(html: string): string[] {
  return items(html).map((item) => {
    const ids = [...item.matchAll(/\bid="([^"]+)"/g)].map((match) => match[1]!);
    const hrefs = [...item.matchAll(/\bhref="#([^"]+)"/g)].map((match) => match[1]!);
    const targets = [...new Set(hrefs.filter((href) => ids.includes(href)))];
    expect(targets, "RULE-02: each rule has its own resolving permalink").toHaveLength(1);
    return targets[0]!;
  });
}
function dataStrings(value: unknown): string[] {
  if (typeof value === "string") return [value];
  if (Array.isArray(value)) return value.flatMap(dataStrings);
  if (value && typeof value === "object") return Object.values(value).flatMap(dataStrings);
  return [];
}

let fixture: Awaited<ReturnType<typeof createRulesFixture>>;
beforeAll(async () => {
  fixture = await createRulesFixture();
});
afterAll(() => {
  fixture?.close();
});

for (const renderer of ["Hono", "Kit"] as const) {
  describe(`${renderer} stable house-rule addresses`, () => {
    it("RULE-01 indexes all five rules with native, descriptive jump links", async () => {
      const { html } = await fixture.render(renderer);
      const links = jumpLinks(html);
      expect(links).toHaveLength(5);
      const ids = idsForRules(html);
      expect(links.map((link) => attribute(link, "href"))).toEqual(ids.map((id) => `#${id}`));
      links.forEach((link, index) => {
        expect(accessibleName(link, html)).toContain(RULE_COPY[index]![0]);
        expect(attribute(link, "onclick")).toBe("");
        expect(attribute(link, "tabindex")).not.toBe("-1");
        expect(attribute(link, "aria-hidden")).not.toBe("true");
      });
    });

    it("RULE-02 gives every rule a unique descriptive permalink backed by shared content identity", async () => {
      const { html } = await fixture.render(renderer);
      expect(items(html)).toHaveLength(5);
      const ids = idsForRules(html);
      expect(new Set(ids).size).toBe(5);
      const allIds = [...html.matchAll(/\bid="([^"]+)"/g)].map((match) => match[1]!);
      ids.forEach((id, index) => {
        expect(id).toMatch(/^[a-zA-Z][a-zA-Z0-9_-]*$/);
        expect(allIds.filter((candidate) => candidate === id)).toHaveLength(1);
        expect(dataStrings(rulesContent), "identity lives with the shared rule data").toContain(id);
        const links = [...items(html)[index]!.matchAll(/<a\b[^>]*>[\s\S]*?<\/a>/g)]
          .map(([value]) => value)
          .filter((link) => attribute(link, "href") === `#${id}`);
        expect(links).toHaveLength(1);
        expect(accessibleName(links[0]!, html)).toContain(RULE_COPY[index]![0]);
        expect(attribute(links[0]!, "tabindex")).not.toBe("-1");
        expect(attribute(links[0]!, "aria-hidden")).not.toBe("true");
      });
    });

    it("RULE-03 retains addresses after fixture copy edits, including a long title", async () => {
      const before = idsForRules((await fixture.render(renderer)).html);
      const { html } = await fixture.render(renderer, changedRuleRows());
      expect(html).toContain(LONG_RULE_LABEL);
      expect(html).toContain("Different fixture wording; the same rule must keep its address.");
      expect(idsForRules(html)).toEqual(before);
      expect(accessibleName(jumpLinks(html)[1]!, html)).toContain(LONG_RULE_LABEL);
    });

    it("RULE-04 retains addresses when shared fixture order changes", async () => {
      const before = idsForRules((await fixture.render(renderer)).html);
      const { html } = await fixture.render(renderer, changedRuleRows(true));
      expect(text(items(html)[0]!)).toContain(RULE_COPY[4][0]);
      expect(idsForRules(html)).toEqual([...before].reverse());
      expect(jumpLinks(html).map((link) => attribute(link, "href"))).toEqual(
        [...before].reverse().map((id) => `#${id}`),
      );
    });

    it("RULE-05 preserves exact policy copy/order, list semantics, heading hash, stamp and actions", async () => {
      const { html } = await fixture.render(renderer);
      expect(html).toMatch(/<h1\b[^>]*id="rules-heading"[^>]*>House rules<\/h1>/);
      const rows = items(html);
      expect(rows).toHaveLength(5);
      rows.forEach((item, index) => {
        expect(text(item.match(/<h2\b[^>]*>([\s\S]*?)<\/h2>/)?.[1] ?? "")).toContain(
          RULE_COPY[index]![0],
        );
        expect(text(item.match(/<p\b[^>]*>([\s\S]*?)<\/p>/)?.[1] ?? "")).toBe(RULE_COPY[index]![1]);
      });
      expect(html).toContain('<time datetime="2026-09-01">1 September 2026</time>');
      expect(html).toMatch(
        /<a\b[^>]*href="\/join"[^>]*data-testid="rules-join"[^>]*>Join with Discord<\/a>/,
      );
      expect(html).toContain('href="/">Back to the homepage</a>');
      expect((await fixture.render(renderer, RULES, "invalid-date")).html).not.toContain(
        "rules-last-updated",
      );
    });

    it("RULE-06 remains a public, script-free page when session/DB bindings are unavailable", async () => {
      // The fixture's env Proxy throws on any binding beyond APP_URL/stamp.
      const { html, status, headers } = await fixture.render(renderer);
      expect(status).toBe(200);
      expect(headers["cache-control"]).toBe("public, max-age=3600");
      expect(headers["set-cookie"]).toBeUndefined();
      expect(html).toContain(`rel="canonical" href="${RULE_ORIGIN}/rules"`);
      expect(html).not.toMatch(/<script\b/i);
      if (renderer === "Kit") {
        expect(fixture.csr).toBe(false);
        expect(
          fixture.modules.filter((module) => /(?:^|\/)(?:db|sessions?)(?:[/.]|$)/i.test(module)),
        ).toEqual([]);
      }
    });
  });
}

it("RULE-08 preserves the same shareable addresses across both renderers", async () => {
  const hono = (await fixture.render("Hono")).html;
  const kit = (await fixture.render("Kit")).html;
  const ids = idsForRules(hono);
  expect(ids).toHaveLength(5);
  expect(idsForRules(kit)).toEqual(ids);
});

it("RULE-07 keeps Markdown policy wording and order truthful after identity is added", () => {
  const markdown = mdRules(RULE_ORIGIN, { iso: "2026-09-01", label: "1 September 2026" });
  expect(markdown.match(/^## .+$/gm)).toEqual([
    "## 1. 18+ only",
    "## 2. Respect the room",
    "## 3. Voice-first",
    "## 4. Play fair",
    "## 5. Moderators have the last word",
  ]);
  let position = -1;
  for (const [, body] of RULE_COPY) {
    expect(markdown).toContain(body);
    const next = markdown.indexOf(body);
    expect(next).toBeGreaterThan(position);
    position = next;
  }
  expect(markdown).toContain("Last updated 1 September 2026 (2026-09-01).");
  expect(markdown).toContain(`[Join with Discord](${RULE_ORIGIN}/join)`);
  expect(markdown).toContain(`[Back to the homepage](${RULE_ORIGIN}/)`);
});
